{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    min_sum = sum(seg['minimum'] for seg in segments)
    if budget < min_sum:
        raise ValueError('Budget insufficient')
    cap_sum = sum(seg['capacity'] for seg in segments)
    if budget > cap_sum:
        raise ValueError('Budget exceeds total capacity')
    allocations = [seg['minimum'] for seg in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_idx = -1
        best_value = -1.0
        for idx, seg in enumerate(segments):
            if allocations[idx] >= seg['capacity']:
                continue
            value = seg['importance'] / (allocations[idx] + 1)
            if value > best_value:
                best_value = value
                best_idx = idx
        if best_idx == -1:
            break
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {seg['name']: allocations[idx] for idx, seg in enumerate(segments)}
    total = sum(allocations)
    return {'allocations': allocations, 'by_name': by_name, 'total': total}
"}
